  return [
    Math.min(255,(neon[i][0]+(neon[i+1][0]-neon[i][0])*f)*glow*edge)|0,
    Math.min(255,(neon[i][1]+(neon[i+1][1]-neon[i][1])*f)*glow*edge)|0,
    Math.min(255,(neon[i][2]+(neon[i+1][2]-neon[i][2])*f)*glow*edge)|0
  ];
}
